import time, psutil

def monitor_connections(host: str, interval_s: int) -> list[dict]:
    logs = []
    try:
        while True:
            now = time.time()
            for c in psutil.net_connections(kind='tcp'):
                if c.status == 'ESTABLISHED' and c.laddr.ip == host:
                    logs.append({'timestamp': now, 'src': f'{c.raddr.ip}:{c.raddr.port}'})
            time.sleep(interval_s)
    except KeyboardInterrupt:
        pass
    return logs
