import copy

def _hash(value: str) -> str:
    return hashlib.sha256(value.encode()).hexdigest()

def anonymize_dataset(records: list[dict], fields: list[str]) -> list[dict]:
    anon = []
    for rec in records:
        new_rec = copy.deepcopy(rec)
        for f in fields:
            if f in new_rec and isinstance(new_rec[f], str):
                new_rec[f] = _hash(new_rec[f])
        anon.append(new_rec)
    return anon
