def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    """Return packets that look suspicious."""
    # simple rules
    blacklisted_ips = {"10.0.0.66", "192.0.2.123"}
    unusual_ports = {0, 1, 7, 19, 23, 37, 111, 135, 137, 138, 139, 445, 1433, 1521, 6667}
    payload_threshold = 1_000_000  # bytes

    # count failed auth attempts per src
    fail_counts = {}
    for p in packet_log:
        if p.get("type") == "auth" and not p.get("success", True):
            fail_counts[p.get("src_ip")] = fail_counts.get(p.get("src_ip"), 0) + 1

    suspicious = []
    for p in packet_log:
        src = p.get("src_ip")
        dst = p.get("dst_ip")
        dport = p.get("dst_port")
        size = p.get("size", 0)

        if src in blacklisted_ips or dst in blacklisted_ips:
            suspicious.append(p)
        elif dport in unusual_ports:
            suspicious.append(p)
        elif size > payload_threshold:
            suspicious.append(p)
        elif fail_counts.get(src, 0) > 5:
            suspicious.append(p)

    return suspicious
