import pyshark
import math
from collections import Counter

def _entropy(s: str) -> float:
    p = Counter(s)
    total = len(s)
    return -sum((c/total) * math.log2(c/total) for c in p.values())

def analyze_dns_traffic(pcap_file: str) -> dict:
    cap = pyshark.FileCapture(pcap_file, display_filter='dns')
    suspicious = set()
    for pkt in cap:
        try:
            qname = pkt.dns.qry_name
        except AttributeError:
            continue

        # basic heuristics
        if len(qname) > 30:                     # long domain
            suspicious.add(qname)
        elif _entropy(qname) > 4.0:             # high entropy (possible DGA)
            suspicious.add(qname)
        elif qname.count('.') > 4:              # many sub‑domains (tunneling)
            suspicious.add(qname)
        elif any(tld in qname for tld in ['.exe', '.zip', '.pdf']):  # exfil payload
            suspicious.add(qname)
    cap.close()
    return {"suspicious_domains": list(suspicious)}
```

